import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

public class CustomUserCrudHarness {
    interface UserGateway { String normalize(String value); }

    @Test
    void echoesNormalizedName() {
        UserGateway gateway = mock(UserGateway.class);
        when(gateway.normalize("alice")).thenReturn("alice");

        Solution solution = new Solution();
        String actual = solution.solve(gateway.normalize("alice"));

        assertEquals("alice", actual);
        verify(gateway).normalize("alice");
    }
}
